#include <iostream>
#include <string>
using namespace std;
​
// 中文数字对应表
const string digitMap[10] = { "零", "壹", "贰", "叁", "肆", "伍", "陆", "柒", "捌", "玖" };
​
// 单位表（个、拾、佰、仟、万、亿）
const string unitMap[17] = {
    "", "拾", "佰", "仟", "万", "拾", "佰", "仟",
    "亿", "拾", "佰", "仟", "万", "拾", "佰", "仟", "万"
};
​
// 处理小数部分（角分）
void readFractionPart(const string& fraction) {
    if (fraction == "00") {
        cout << "整";
        return;
    }
    if (fraction[0] > '0') {
        cout << digitMap[fraction[0] - '0'] << "角";
    }
    if (fraction[1] > '0') {
        cout << digitMap[fraction[1] - '0'] << "分";
    }
}
​
// 处理整数部分（元以上）
void readIntegerPart(const string& integer) {
    if (integer == "0") return;
​
    int len = integer.size();
​
    // 特殊处理：10 读作 拾 而不是壹拾
    if (!((len - 1) % 4 == 1 && integer[0] == '1')) {
        cout << digitMap[integer[0] - '0'];
    }
    cout << unitMap[len - 1];
​
    for (int i = 1; i < len; ++i) {
        int digit = integer[i] - '0';
        int unitPos = len - 1 - i;
​
        // 判断是否为每组最后一位（用于加单位“万”、“亿”）
        if (unitPos % 4 == 0 && integer[i] == '0') {
            // 处理例如：100000001.11 的“万”不读出多个零
            if (i >= 4 && unitPos == 4 &&
                integer[i - 1] == '0' &&
                integer[i - 2] == '0' &&
                integer[i - 3] == '0') {
                continue;
            }
            cout << unitMap[unitPos];
            continue;
        }
​
        if (digit != 0) {
            // 前一位为零时，补读“零” 多位零也只会补充一个
            if (integer[i - 1] == '0') {
                cout << "零";
            }
            cout << digitMap[digit] << unitMap[unitPos];
        }
    }
​
    cout << "元";
}
​
int main() {
    string money;
​
    getline(cin, money);
    if (money == "0.00" || money == "0" || money == "0.0") {
        cout << "人民币零元整";
        return 0;
    }
    int dotPos = money.find('.');
    string integerPart = money.substr(0, dotPos);
    string fractionPart = money.substr(dotPos + 1);
​
    cout << "人民币";
    readIntegerPart(integerPart);
    readFractionPart(fractionPart);
​

​
    return 0;
}
