// 处理整数部分
function readIntegerPart(integer) {
    if (integer === "0") return "";
    let result = [];
    let len = integer.length;
    if (!((len - 1) % 4 === 1 && integer[0] === '1')) {
        result.push(digitMap[+integer[0]]);
    }
    result.push(unitMap[len - 1]);
​
    for (let i = 1; i < len; i++) {
        let digit = +integer[i];
        let unitPos = len - 1 - i;
        if (unitPos % 4 === 0 && digit === 0) {
            if (i >= 4 && unitPos === 4 &&
                integer[i - 1] === '0' &&
                integer[i - 2] === '0' &&
                integer[i - 3] === '0') {
                continue;
            }
            result.push(unitMap[unitPos]);
            continue;
        }
        if (digit !== 0) {
            if (integer[i - 1] === '0') result.push("零");
            result.push(digitMap[digit] + unitMap[unitPos]);
        }
    }
    return result.join('') + "元";
}
