// 处理小数部分
function readFractionPart(fraction) {
    if (fraction === "00") return "整";
    let result = [];
    if (fraction[0] > '0') {
        result.push(digitMap[+fraction[0]] + "角");
    }
    if (fraction[1] > '0') {
        result.push(digitMap[+fraction[1]] + "分");
    }
    return result.join('');
}
