import (
    "fmt"
    "strings"
)
​
var digitMap = []string{"零", "壹", "贰", "叁", "肆", "伍", "陆", "柒", "捌", "玖"}
var unitMap = []string{
    "", "拾", "佰", "仟", "万", "拾", "佰", "仟",
    "亿", "拾", "佰", "仟", "万", "拾", "佰", "仟", "万",
}
​
// 处理整数部分
func readIntegerPart(integer string) string {
    if integer == "0" {
        return ""
    }
    var result strings.Builder
    length := len(integer)
    if !((length-1)%4 == 1 && integer[0] == '1') {
        result.WriteString(digitMap[integer[0]-'0'])
    }
    result.WriteString(unitMap[length-1])
    for i := 1; i < length; i++ {
        digit := integer[i] - '0'
        unitPos := length - 1 - i
        if unitPos%4 == 0 && digit == 0 {
            if i >= 4 && unitPos == 4 &&
                integer[i-1] == '0' &&
                integer[i-2] == '0' &&
                integer[i-3] == '0' {
                continue
            }
            result.WriteString(unitMap[unitPos])
            continue
        }
        if digit != 0 {
            if integer[i-1] == '0' {
                result.WriteString("零")
            }
            result.WriteString(digitMap[digit])
            result.WriteString(unitMap[unitPos])
        }
    }
    result.WriteString("元")
    return result.String()
}
​
// 处理小数部分
func readFractionPart(fraction string) string {
    if fraction == "00" {
        return "整"
    }
    var result strings.Builder
    if fraction[0] > '0' {
        result.WriteString(digitMap[fraction[0]-'0'] + "角")
    }
    if fraction[1] > '0' {
        result.WriteString(digitMap[fraction[1]-'0'] + "分")
    }
    return result.String()
}
​
func main() {
    var money string
    fmt.Scanln(&money)
    if money == "0.00" || money == "0" || money == "0.0" {
        fmt.Println("人民币零元整")
        return
    }
    parts := strings.Split(money, ".")
    integerPart := parts[0]
    fractionPart := parts[1]
    fmt.Print("人民币")
    fmt.Print(readIntegerPart(integerPart))
    fmt.Print(readFractionPart(fractionPart))
}
